using System;
using Windows.Storage.Streams;
using Windows.UI.Xaml.Media.Imaging;

namespace KillConfirmGameBar
{
    public sealed partial class KillConfirmWidgetPage
    {
        // Exact toolbar reference supplied for the click-through setup guide.
        private const string ClickThroughGuideImageBase64 =
            "";

        private async void InitializeGameBarSetupGuideImage()
        {
            if (ClickThroughSetupGuideImage == null)
            {
                return;
            }

            try
            {
                byte[] imageBytes = Convert.FromBase64String(ClickThroughGuideImageBase64);
                using (InMemoryRandomAccessStream stream = new InMemoryRandomAccessStream())
                {
                    using (DataWriter writer = new DataWriter(stream.GetOutputStreamAt(0)))
                    {
                        writer.WriteBytes(imageBytes);
                        await writer.StoreAsync();
                        await writer.FlushAsync();
                        writer.DetachStream();
                    }

                    stream.Seek(0);
                    BitmapImage image = new BitmapImage
                    {
                        DecodePixelWidth = 281,
                        DecodePixelHeight = 176
                    };
                    await image.SetSourceAsync(stream);
                    ClickThroughSetupGuideImage.Source = image;
                }
            }
            catch (Exception)
            {
                // The text instruction remains usable if the optional image
                // cannot be decoded on a particular Game Bar build.
            }
        }
    }
}

